INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (6, '2026-08-11', 'shipment_return', 90, 'Return received from UD Mainan Ceria: 90 pcs Blister Pack Custom Logo from PO batch shipped 2026-08-08 (ref nota series INV/2608/2-*). Customer flagged the printed logo color looked washed out compared to the approved proof. Boxes brought back to warehouse intact, units re-added to stock pending QC inspection before resale.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (6, '2026-08-12', 'stock_defect', -55, 'QC inspection of the 90 pcs returned from UD Mainan Ceria on 2026-08-11 (see return note). Pulled each unit under the color-match light box against the approved master proof: 55 pcs show a clear logo color shift (CMYK mix ran light on cyan, printer calibration drifted mid-run). These are written off as defective and will not be resold. Remaining 35 pcs matched the proof within tolerance and were returned to sellable stock. Inspected by Lisa Cu; root cause reported to the print vendor for the next batch.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (9, '2026-08-20', 'stock_out', -25, 'Internal draw: 25 pack Mika Amplop A4 taken from the warehouse for the office front-desk and sample-kit restock (not for resale). Logged separately from sales so it does not inflate customer-facing revenue figures. Approved verbally by Rudi Salim, recorded by Lisa Cu.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (7, '2026-09-09', 'shipment_return', 50, 'Return received from PT Kosmetik Abadi Sentosa: 50 pcs Vacuum Blister Tray Custom from the order shipped 2026-09-04. Customer reported the tray depth did not match their new jar mold dimensions after a late spec change on their end. Units brought back sealed in original cartons, pending inspection.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (7, '2026-09-10', 'stock_defect', -50, 'Inspected all 50 pcs Vacuum Blister Tray Custom returned from PT Kosmetik Abadi Sentosa on 2026-09-09. These were molded to the OLD jar spec per the original PO and cannot be reused against the customer''s new jar dimensions or any other current order -- the tooling profile does not match any other active account. Entire batch written off as defective/unsellable rather than restocked. Inspected by Lisa Cu; customer informed a re-run will be quoted separately against the new spec.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (3, '2026-09-18', 'adjust_up', 8, 'Physical recount of Mika Roll Bening 0.3mm during the September stock opname found 8 more rolls on the shelf than the running ledger showed. Likely a prior delivery that was shelved but never logged as a stock-in. Correcting the ledger upward to match the physical count. Counted and logged by Lisa Cu.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (11, '2026-10-16', 'shipment_return', 70, 'Return received from UD Herbal Sehat Alami: 70 pcs Double Blister Card from the order shipped 2026-10-11. Customer said the card stock felt thinner than their usual spec and was concerned about the card bending during their packing line. Units returned unopened, pending inspection.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (11, '2026-10-17', 'stock_defect', -40, 'Inspected the 70 pcs Double Blister Card returned from UD Herbal Sehat Alami on 2026-10-16. Measured card thickness against spec with calipers: 40 pcs came from a sub-spec paperboard sheet (supplier substituted a thinner stock mid-run without flagging it) and are written off as defective. The remaining 30 pcs measured within spec and were cleaned, re-boxed and returned to sellable stock. Inspected by Lisa Cu; flagged to the board-stock supplier.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (5, '2026-10-22', 'stock_out', -60, 'Internal draw: 60 pcs Blister Pack Standar A5 pulled for an in-house product photography and sample-kit session ahead of the Q4 customer catalog refresh. Not a sale, logged separately. Recorded by Lisa Cu.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (12, '2026-10-30', 'adjust_down', -18, 'October stock opname for Mika Tebal 1mm Super Clear came up 18 sheets short of the ledger balance. No return, defect or draw on record that would explain it. Logged as an unexplained shrinkage adjustment pending the next recount; warehouse team asked to double-check storage racking in case sheets were miscounted into the 0.5mm bin. Recorded by Lisa Cu.', 'd8ae46f3-7592-457f-b024-112def649953');
INSERT INTO stock_ledger (sku_id, date, movement_type, qty, note, created_by) VALUES (8, '2026-11-04', 'stock_out', -15, 'Internal draw: 15 lembar Mika Warna (Merah/Biru/Kuning) taken for a vendor sample packet requested by a prospective new customer. Not a sale, logged separately. Recorded by Lisa Cu.', 'd8ae46f3-7592-457f-b024-112def649953');
